import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class ContractTest{static String capture(Runnable action){PrintStream previous=System.out,oldErr=System.err;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);System.setErr(out);action.run();}finally{System.setOut(previous);System.setErr(oldErr);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void repeatedGrowthAndRefill(){Object q=TaskBinding.queue(1);assertEquals("Очередь пуста\n",capture(()->assertEquals('\0',TaskBinding.get(q))));assertEquals("",capture(()->{for(char c=1;c<=20;c++)TaskBinding.put(q,c);for(char c=1;c<=20;c++)assertEquals(c,TaskBinding.get(q));TaskBinding.put(q,'X');assertEquals('X',TaskBinding.get(q));}));}}
